import json

for split in ['train', 'val', 'test']:
    with open(f'{split}.jsonl') as f:
        data = [json.loads(l) for l in f]
    labels = {}
    sources = {}
    for d in data:
        labels[d['label']] = labels.get(d['label'], 0) + 1
        sources[d['source']] = sources.get(d['source'], 0) + 1
    print(f'{split}: {len(data)} total | labels={labels} | sources={sources}')
    # Check if placeholder responses were fixed
    placeholder_count = 0
    for d in data:
        for t in d['turns']:
            if t['role'] == 'assistant' and t['content'] == '[Model response]':
                placeholder_count += 1
                break
    print(f'  conversations with placeholder assistant: {placeholder_count}')
